import {designWidth} from './phone-layout.mjs?v=1.0.2';
import {sampleScreenControls,tapMotion,screenPadMarkup,SCREEN_KEYS} from './screen-driving.mjs';
import {createHeist,restoreHeist,applyHeistAction,advanceHeist,nearCar,locationName,TARGET,TOKENS,WORLD,BUILDINGS} from './heist-core.mjs?v=1.0.1';
import {makeCity,drawCity,portrait,dashboard,puzzleSvg} from './heist-art.mjs';
const app=document.querySelector('#heist-app'),modal=document.querySelector('#heist-modal'),$=q=>document.querySelector(q),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tap=null,turbo=false;
let state=null,context=null,city=null,canvas=null,frame=0,lastFrame=0,lastSaved=0,lastHud=0,keyDown=new Map(),padDown=new Map(),helpOpen=false,focusBefore=null,toastTimer=0,reportedFailure=false;
const solo=()=>['heist-free','activation-free','lt32-free'].includes(context?.mode);
const saveKey=()=>solo()?'andersons-heist-solo-v1':'andersons-heist-campaign-v1';
const tell=(event,payload={})=>{if(parent!==window)parent.postMessage({type:'andersons-heist',event,payload},location.origin);};
const token=id=>TOKENS.find(t=>t.id===id);
function save(){if(state&&!['caught','gameover'].includes(state.phase))try{localStorage.setItem(saveKey(),JSON.stringify(state));}catch{}}
function toast(message){const el=$('#heist-toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
const audio={ctx:null,sirens:[],play(kind){if(context?.prefs?.sound===false)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{});const now=this.ctx.currentTime,notes=kind==='engine'?[90,120,155,195]:kind==='end'?[294,220,147]:kind==='alarm'?[650,940,650,940,650,940]:[700];notes.forEach((n,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=kind==='alarm'?'triangle':kind==='engine'?'sawtooth':'sine';o.frequency.value=n;const t=now+i*(kind==='alarm'?.32:.1);g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.0001,t+.3);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+.32);});}catch{}}};
const controls={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
function updateDriveButtons(){const b=app.querySelector('[data-action="turbo"]');if(b){b.classList.toggle('active',turbo);b.setAttribute('aria-pressed',String(turbo));b.setAttribute('aria-label',(turbo?'Desativar':'Ativar')+' turbo');b.querySelector('span').textContent='TURBO: '+(turbo?'ON':'OFF');}}
function clearInput(){keyDown.clear();padDown.clear();tap=null;turbo=false;document.querySelectorAll('[data-pad]').forEach(b=>b.classList.remove('held'));updateDriveButtons();}
function camera(){const rect=canvas?.getBoundingClientRect()||{width:1100,height:620},w=Math.max(640,Math.min(1200,canvas?designWidth(canvas):rect.width)),h=w*rect.height/Math.max(1,rect.width);if(['drive','starting','caught','gameover','finish'].includes(state.phase)&&state.escapeView)return state.escapeView;return {x:Math.max(0,Math.min(WORLD.width-w,state.actor.x-w/2)),y:Math.max(0,Math.min(WORLD.height-h,state.actor.y-h/2)),w,h};}
function minimap(){return `<svg id="mini-map" viewBox="0 0 ${WORLD.width} ${WORLD.height}" role="img" aria-label="Minimapa da cidade. O ponto amarelo é Anderson."><rect width="2200" height="1480" fill="#223d40"/>${BUILDINGS.map(b=>`<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="#5a6b5c"/>`).join('')}<g stroke="#a3ad8955" stroke-width="55">${WORLD.roadX.map(x=>`<path d="M${x} 0V1480"/>`).join('')}${WORLD.roadY.map(y=>`<path d="M0 ${y}H2200"/>`).join('')}</g><rect id="mini-view" x="0" y="0" width="1000" height="600" fill="none" stroke="#dfcc8d" stroke-width="11"/><circle id="mini-ka" cx="${TARGET.x}" cy="${TARGET.y}" r="40" fill="#7fb9c2" style="display:none"/><circle id="mini-player" cx="${state.actor.x}" cy="${state.actor.y}" r="39" fill="#f1c570" aria-label="Anderson no minimapa"/></svg>`;}
const objective=()=>({intro:'Um novo Anderson entra em cena.',foot:state.discovered?'Ford Ka encontrado. Chegue perto e entre no carro.':'Encontre o Ford Ka azul na Rua das Oficinas.',interior:'Você está no Ford Ka. Abra o painel.',wiring:'Complete os três circuitos do módulo de partida.',starting:'O motor está ligando…',drive:'O motor ligou. Saia da tela dirigindo o Ford Ka.',caught:'ALARME DISPARADO. A POLÍCIA ESTÁ CHEGANDO.',gameover:'Anderson foi preso.',finish:'Anderson saiu de cena. E aí…'}[state.phase]);
function header(){return `<header class="heist-top"><a href="./" class="brand" data-action="menu"><b>A</b> OS ANDERSONS</a><span class="top-label">ATO 04 / UM OUTRO ANDERSON</span><nav><button data-action="sound">${context.prefs?.sound===false?'Som desligado':'Som ligado'}</button><button data-action="help">Controles</button><button data-action="menu">${solo()?'Menu do jogo':'Salvar e sair'}</button></nav></header>`;}
function hud(){return `<div class="heist-hud"><div class="chapter"><span>04</span><div><small>ANDERSON / O LADRÃO</small><h1>O GRANDE ROUBO</h1></div></div><div class="mission"><small>OBJETIVO ATUAL</small><p id="mission-text">${objective()}</p></div><div class="heat"><small>SITUAÇÃO</small><strong id="heat-label">${['caught','gameover'].includes(state.phase)?'PROCURADO':'SEM SUSPEITA'}</strong></div></div>`;}
function directionPad(){if(state.phase==='drive')return screenPadMarkup(turbo);return `<div class="direction-pad" role="group" aria-label="Controles de movimento"><button data-pad="up" class="up" aria-label="Andar para cima">↑</button><button data-pad="left" class="left" aria-label="Andar para a esquerda">←</button><span class="pad-center">A</span><button data-pad="right" class="right" aria-label="Andar para a direita">→</button><button data-pad="down" class="down" aria-label="Andar para baixo">↓</button></div>`;}
function worldView(){const foot=state.phase==='foot',caught=['caught','gameover'].includes(state.phase);return `<section class="city-stage ${caught?'police-arrival':''}" aria-label="Cidade vista de cima"><canvas id="city-canvas" tabindex="0" aria-label="${state.phase==='drive'?'Setas ou WASD movem o Ford Ka na direção da tela. Espaço freia. Shift ou Turbo aumenta a velocidade.':'Cidade 2D vista de cima. Use as setas ou WASD para andar; E para entrar no Ford Ka.'}"></canvas><div class="city-corner"><i></i> <span id="world-location">${locationName(state.phase==='drive'?state.car:state.actor)}</span></div><div class="mini-panel"><span>N ↑ / ANDERSON CITY</span>${minimap()}</div>${['foot','drive'].includes(state.phase)?`<div class="world-controls">${directionPad()}<div class="action-controls">${foot?`<button class="enter-button" id="enter-car" data-action="enter" ${nearCar(state)?'':'disabled'}><kbd>E</kbd><span>${nearCar(state)?'Entrar no Ford Ka':'Aproxime-se do Ford Ka'}</span></button>`:'<div class="drive-note"><b>FORD KA</b><span>← ↑ ↓ → Mover na tela<br>Espaço = freio · Shift = turbo</span></div>'}</div></div>`:''}${state.phase==='intro'?introCard():caught?`<div class="police-caption"><b>★ ALARME DISPARADO ★</b><span>A polícia localizou o Ford Ka.</span></div>`:''}</section>`;}
function introCard(){return `<div class="intro-cover"><section class="intro-card" role="dialog" aria-labelledby="intro-title" aria-modal="false"><div class="character-photo">${portrait()}<span>MAIS UM ANDERSON.</span></div><div class="intro-copy"><span class="eyebrow">ATO 04 / O GRANDE ROUBO</span><h2 id="intro-title">ANDERSON.<br>O LADRÃO.</h2><p>Enquanto uns agendam e outros instalam, este Anderson está dando uma volta pela cidade.</p><p>Há um <strong>Ford Ka azul</strong> estacionado na <strong>Rua das Oficinas</strong>. Encontre o carro e chegue perto para entrar.</p><button class="primary" data-action="begin">Entrar na cidade →</button><small>WASD ou setas · E para entrar<br>No celular: setas na tela ou toque na rua para andar.</small></div></section></div>`;}
function interiorView(){const open=state.phase!=='interior',selected=state.puzzle.wires.find(w=>w.id===state.selected),count=Object.keys(state.connections).length;return `<section class="interior-stage"><div class="interior-cap"><span>FORD KA / VISTA DE DENTRO</span><b>${state.phase==='starting'?'DANDO PARTIDA…':open?count+' / 3 CIRCUITOS':'PAINEL FECHADO'}</b></div>${open?`<div class="panel-heading"><span class="eyebrow">PAINEL ABERTO / MÓDULO DE PARTIDA</span><h2>Encontre os símbolos certos.</h2><p>Examine um cabo, siga seu símbolo e conecte no encaixe correspondente. O alarme não aceita erro.</p></div>${puzzleSvg(state)}<div class="puzzle-controls"><section><span class="control-title">1 / EXAMINE UM CABO</span><div class="heist-cable-list">${state.puzzle.wires.map(w=>{const used=Object.values(state.connections).includes(w.id);return `<button data-action="select-wire" data-id="${w.id}" class="${state.selected===w.id?'selected':''}" ${used?'disabled':''} aria-label="Selecionar cabo ${w.letter}"><i style="--cable:${w.color}"></i>Cabo ${w.letter}<small>${used?'✓':'↗'}</small></button>`;}).join('')}</div><div class="cable-probe" aria-live="polite">${selected?`<b>${token(selected.token).symbol}</b><span>CABO ${selected.letter}<strong>${token(selected.token).name}</strong></span>`:'<span>Escolha um dos cabos A–L.<strong>O símbolo mostra o encaixe correto.</strong></span>'}</div></section><section><span class="control-title">2 / CONECTE NO MESMO SÍMBOLO</span><div class="socket-controls">${state.puzzle.sockets.map(p=>{const t=token(p.token),used=!!state.connections[p.id];return `<button data-action="connect" data-id="${p.id}" ${used?'disabled':''}><b>${t.symbol}</b><span>Encaixe ${p.name}<strong>${t.name}</strong></span><small>${used?'✓':'↗'}</small></button>`;}).join('')}</div><button class="primary engine-button" data-action="start-engine" ${state.phase==='starting'?'disabled':''}>${state.phase==='starting'?'Motor ligando…':'Dar partida no Ford Ka →'}</button><p class="puzzle-note">${count===3?'Três circuitos conectados. Pode dar partida.':'Complete os três circuitos antes de tentar ligar.'}</p></section></div>`:`${dashboard()}<div class="closed-panel"><p>Anderson está no banco do motorista.<br>O carro ainda não ligou.</p><button class="primary" data-action="open-panel">Abrir painel ↓</button></div>`}${state.phase==='starting'?'<div class="engine-starting"><div class="engine-spin"></div><strong>O MOTOR PEGOU.</strong><span>Prepare-se para dirigir.</span></div>':''}<div class="arcade-label">PARTIDA ARCADE / SÍMBOLOS DO JOGO</div></section>`;}
function endView(){return `<section class="heist-ending"><div class="end-road"></div><span class="eyebrow">ANDERSON SAIU DE CENA.</span><h2>E AÍ<span>…</span></h2><p>FIM DO ATO 4</p><div class="end-buttons"><button class="primary" data-action="recovery">Continuar para Atuação anti furto →</button><button data-action="menu">Voltar ao início</button><button data-action="new-case">Começar outro expediente →</button></div></section>`;}
function render(){if(!state)return;document.body.classList.toggle('reduce-motion',!!context.prefs?.reduceMotion);app.innerHTML=header()+`<main class="heist-main">${state.phase==='finish'?endView():`${hud()}${['interior','wiring','starting'].includes(state.phase)?interiorView():worldView()}<footer class="heist-footer"><span>${state.phase==='drive'?'SETAS / WASD = DIREÇÃO NA TELA · ESPAÇO = FREIO · SHIFT = TURBO':'WASD OU SETAS PARA ANDAR · E PARA ENTRAR'}</span><span>OS ANDERSONS / ATO 04</span></footer>`}</main>`;canvas=$('#city-canvas');if(state.phase==='intro')app.querySelector('[data-action="begin"]')?.focus({preventScroll:true});if(state.phase==='gameover')showGameover();updateHud();}
function updateHud(){if(!state)return;const mission=$('#mission-text');if(mission)mission.textContent=objective();const button=$('#enter-car');if(button){const near=nearCar(state);button.disabled=!near;button.querySelector('span').textContent=near?'Entrar no Ford Ka':'Aproxime-se do Ford Ka';button.classList.toggle('near',near);}const street=$('#world-location');if(street)street.textContent=locationName(state.phase==='drive'?state.car:state.actor);if(state.phase==='drive'){const heat=$('#heat-label');if(heat)heat.textContent='FUGINDO';}}
function report(){if(state.phase==='caught'&&!reportedFailure){reportedFailure=true;try{localStorage.removeItem(saveKey());}catch{}tell('failed',{phase:'caught'});audio.play('alarm');}else if(state.phase==='finish'){tell('complete',{phase:'finish'});audio.play('end');}else tell('progress',{phase:state.phase});}
function update(action){if(!state||helpOpen)return;const previous=state.phase,next=applyHeistAction(state,action);if(next===state){if(action.type==='connect'&&!state.selected)toast('Primeiro selecione um cabo para examinar o símbolo.');return;}state=next;save();if(previous!==state.phase)clearInput();render();if(['select-wire','connect','open-panel'].includes(action.type))audio.play('tick');if(state.phase==='starting')audio.play('engine');if(previous!==state.phase){window.scrollTo(0,0);report();}}
function input(){return sampleScreenControls(keyDown,padDown,{now:performance.now(),tap,turbo});}
function nudge(direction){if(!['foot','drive'].includes(state.phase)||helpOpen||!controls[direction])return;if(state.phase==='drive'){tap={direction,until:performance.now()+140};return;}const [x,y]=controls[direction],previous=state.phase;for(let i=0;i<6;i++)state=advanceHeist(state,{x,y},.05);if(previous!==state.phase){clearInput();render();report();save();}updateHud();}
function draw(now){const dt=lastFrame?Math.min(.05,(now-lastFrame)/1000):0;lastFrame=now;if(state&&!document.hidden&&!helpOpen){const previous=state.phase;state=advanceHeist(state,input(),dt);if(previous!==state.phase){clearInput();save();render();report();}if(canvas){const v=camera();drawCity(canvas,city,state,v,context.prefs);const p=state.phase==='drive'?state.car:state.actor,mini=$('#mini-player'),bounds=$('#mini-view'),ka=$('#mini-ka');if(mini){mini.setAttribute('cx',p.x);mini.setAttribute('cy',p.y);}if(bounds)for(const [key,value]of Object.entries({x:v.x,y:v.y,width:v.w,height:v.h}))bounds.setAttribute(key,value);if(ka)ka.style.display=state.discovered?'':'none';}if(now-lastHud>120){lastHud=now;updateHud();}if(now-lastSaved>2000){lastSaved=now;save();}}}
function exit(event='menu'){save();clearInterval(frame);clearInput();if(parent===window)location.href='./';else tell(event);}
function showGameover(){app.inert=true;modal.innerHTML=`<div class="modal-cover"><section class="arrest-dialog" role="dialog" aria-modal="true" aria-labelledby="arrest-title"><div class="police-lights"><i></i><b>POLÍCIA / OCORRÊNCIA #004</b><i></i></div><span class="eyebrow">O GRANDE ROUBO DEU ERRADO.</span><h2 id="arrest-title">ANDERSON<br>FOI PRESO.</h2><p>${esc(state.failure)}</p><strong class="game-over">GAME OVER</strong><button class="primary" data-action="menu">Voltar ao início →</button></section></div>`;modal.querySelector('button').focus();}
function showHelp(){if(['caught','gameover'].includes(state.phase))return;clearInput();helpOpen=true;focusBefore=document.activeElement;app.inert=true;modal.innerHTML=`<div class="modal-cover"><section class="help-dialog" role="dialog" aria-modal="true" aria-labelledby="help-title"><header><h2 id="help-title">Controles do Ato 4</h2><button data-action="close-help">Fechar</button></header><dl><div><dt>A pé</dt><dd>WASD ou setas para andar. Shift para correr. Clique ou toque numa rua para caminhar até ela.</dd></div><div><dt>Entrar no Ka</dt><dd>Chegue perto do Ford Ka azul e use E ou “Entrar no Ford Ka”.</dd></div><div><dt>Painel</dt><dd>Examine os cabos e ligue símbolos iguais. São três circuitos do módulo arcade. Errar chama a polícia.</dd></div><div><dt>Dirigir</dt><dd>As setas e WASD indicam a direção da tela: cima vai para cima, baixo para baixo, esquerda para a esquerda e direita para a direita. O carro se vira sozinho. Solte as setas para parar. Espaço ou FREIO também param. Shift ou o botão Turbo aumentam a velocidade. No celular, toque ou segure as setas. Saia da tela para concluir o ato.</dd></div></dl><button class="primary" data-action="close-help">Voltar ao jogo</button></section></div>`;modal.querySelector('button').focus();}
function closeHelp(){if(!helpOpen)return;helpOpen=false;modal.innerHTML='';app.inert=false;lastFrame=0;focusBefore?.isConnected&&focusBefore.focus({preventScroll:true});}
function dispatch(action,id){if(action==='menu')return exit();if(action==='new-case')return exit('new-case');if(action==='recovery'&&state.phase==='finish'){save();clearInterval(frame);if(parent===window)location.href='./recovery.html';else tell('recovery');return;}if(action==='turbo'&&state.phase==='drive'){turbo=!turbo;updateDriveButtons();return;}if(action==='help')return showHelp();if(action==='close-help')return closeHelp();if(action==='sound'){if(parent===window){context.prefs.sound=context.prefs.sound===false;render();}else tell('sound');return;}if(action==='enter')return update({type:'enter',view:camera()});if(['begin','open-panel','select-wire','connect','start-engine'].includes(action))return update({type:action,id});}
for(const root of [app,modal])root.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!target.disabled){event.preventDefault();dispatch(target.dataset.action,target.dataset.id);}});
app.addEventListener('click',event=>{if(event.target.id!=='city-canvas'||state.phase!=='foot'||helpOpen)return;const rect=canvas.getBoundingClientRect(),v=camera();update({type:'walk-to',x:v.x+(event.clientX-rect.left)/rect.width*v.w,y:v.y+(event.clientY-rect.top)/rect.height*v.h});});
app.addEventListener('pointerdown',event=>{const pad=event.target.closest('[data-pad]');if(!pad||!['foot','drive'].includes(state.phase)||helpOpen)return;event.preventDefault();pad.setPointerCapture?.(event.pointerId);tap=null;padDown.set(event.pointerId,{direction:pad.dataset.pad,time:performance.now()});pad.classList.add('held');});
function releasePad(event){const held=padDown.get(event.pointerId);if(!held)return;padDown.delete(event.pointerId);app.querySelectorAll('[data-pad]').forEach(b=>b.classList.toggle('held',[...padDown.values()].some(p=>p.direction===b.dataset.pad)));const short=event.type==='pointercancel'?null:tapMotion(held.direction,held.time,performance.now());if(event.type==='pointercancel')tap=null;if(short){if(state.phase==='drive')tap=short;else nudge(held.direction);}}
document.addEventListener('pointerup',releasePad);document.addEventListener('pointercancel',releasePad);
const keyMap=SCREEN_KEYS;
document.addEventListener('keydown',event=>{if(modal.children.length){if(event.key==='Escape'&&helpOpen){event.preventDefault();closeHelp();}if(event.key==='Tab'){const all=[...modal.querySelectorAll('button')],first=all[0],last=all.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}return;}if(['Enter',' '].includes(event.key)&&event.target.matches('g[data-action]')){event.preventDefault();dispatch(event.target.dataset.action,event.target.dataset.id);return;}const direction=keyMap[event.key]||keyMap[event.key.toLowerCase()];if(direction&&['foot','drive'].includes(state.phase)&&(direction!=='brake'||state.phase==='drive')){event.preventDefault();if(!keyDown.has(direction)){tap=null;keyDown.set(direction,performance.now());}}if(event.key.toLowerCase()==='e'&&state.phase==='foot'){event.preventDefault();dispatch('enter');}if(event.key==='Escape'){event.preventDefault();showHelp();}});
document.addEventListener('keyup',event=>{const direction=keyMap[event.key]||keyMap[event.key.toLowerCase()];if(!direction)return;const started=keyDown.get(direction);keyDown.delete(direction);const short=tapMotion(direction,started,performance.now());if(short){if(state.phase==='drive')tap=short;else nudge(direction);}});
window.addEventListener('blur',clearInput);window.addEventListener('pagehide',()=>{save();clearInterval(frame);});document.addEventListener('visibilitychange',()=>{clearInput();lastFrame=0;if(document.hidden){save();audio.ctx?.suspend().catch(()=>{});}else if(context?.prefs?.sound!==false)audio.ctx?.resume().catch(()=>{});});
function initialize(payload){if(state){context={...context,...payload,prefs:payload.prefs||context.prefs};render();return;}context={...payload,prefs:payload.prefs||{}};let raw=null;try{raw=JSON.parse(localStorage.getItem(saveKey()));}catch{}state=restoreHeist(raw,context.caseId)||createHeist(context.caseId);city=makeCity();render();save();tell(state.phase==='finish'?'complete':'progress',{phase:state.phase});lastFrame=performance.now();frame=setInterval(()=>draw(performance.now()),16);}
window.addEventListener('message',event=>{if(event.source===parent&&event.origin===location.origin&&event.data?.type==='andersons-context'&&event.data.payload?.caseId)initialize(event.data.payload);});
tell('ready');if(parent===window)initialize({caseId:'heist-standalone-'+Date.now().toString(36),mode:'heist-free',prefs:{sound:true,reduceMotion:matchMedia('(prefers-reduced-motion: reduce)').matches}});
